def solve(n):
    if n <= 2:
        return 0
    import math
    size = (n + 1) // 2
    sieve = bytearray(b'\x01') * size
    sieve[0] = 0
    sq = int(math.isqrt(n)) + 1
    for i in range(3, sq, 2):
        if sieve[i // 2]:
            start = (i * i) // 2
            step = i
            sieve[start:size:step] = b'\x00' * ((size - 1 - start) // step + 1)
    return 1 + sum(sieve)

