def solve(m):
    n = len(m)
    if n == 0:
        return 1
    if n == 1:
        return m[0][0]
    if n == 2:
        return m[0][0]*m[1][1] - m[0][1]*m[1][0]
    # cofactor expansion along first row
    total = 0
    for c in range(n):
        # build submatrix without row 0 and column c
        sub = [m[r][:c] + m[r][c+1:] for r in range(1, n)]
        sign = -1 if c % 2 else 1
        total += sign * m[0][c] * solve(sub)
    return total

