def solve(a, b):
    m, n = len(a), len(b)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        for j in range(1, n+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]

def solve(tokens):
    stack = []
    for t in tokens:
        if t in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            elif t == '/':
                # truncate toward zero
                v = abs(a) // abs(b)
                if (a < 0) != (b < 0):
                    v = -v
                stack.append(v)
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

def solve(weights, values, capacity):
    n = len(weights)
    dp = [0]*(capacity+1)
    for i in range(n):
        w, v = weights[i], values[i]
        for c in range(capacity, w-1, -1):
            if dp[c-w] + v > dp[c]:
                dp[c] = dp[c-w] + v
    return dp[capacity]

