    # cofactor expansion on first row
    def det_sub(matrix):
        nn = len(matrix)
        if nn == 1:
            return matrix[0][0]
        if nn == 2:
            return matrix[0][0]*matrix[1][1] - matrix[0][1]*matrix[1][0]
        total = 0
        for c in range(nn):
            sub = [row[:c] + row[c+1:] for row in matrix[1:]]
