def solve(m):
    if m==[]:
        return 1
    n=len(m)
    if n==0:
        return 1
    # copy
    a=[row[:] for row in m]
    # handle 1x1 with empty inner? if m=[[]]? treat as 1? but spec says square; ignore
    if len(a[0])==0:
        return 1
    prev=1
    det_sign=1
    for k in range(n-1):
        # pivot if zero: find swap
        if a[k][k]==0:
            swap=-1
            for i in range(k+1,n):
                if a[i][k]!=0:
                    swap=i
                    break
            if swap==-1:
                return 0
            a[k],a[swap]=a[swap],a[k]
            det_sign=-det_sign
        for i in range(k+1,n):
            for j in range(k+1,n):
                a[i][j]=(a[i][j]*a[k][k]-a[i][k]*a[k][j])//prev
